function xz_visit_stats_t3_url($view, $filters = array(), $extra = array())
{
    global $zbp;
    $params = array('view' => $view);
    foreach (xz_visit_stats_v2_drilldown_params($filters, $extra) as $key => $value) if ($key !== 'view') $params[$key] = $value;
    foreach (array('device', 'new_returning', 'country', 'province', 'event_name') as $key) if (isset($filters[$key]) && $filters[$key] !== '' && $filters[$key] !== 'all') $params[$key] = $filters[$key];
    foreach ($extra as $key => $value) if ($key !== 'view' && $value !== '' && $value !== null) $params[$key] = $value;
    return $zbp->host . 'zb_users/plugin/xz_visit_stats/main.php?' . http_build_query($params, '', '&');
}

function xz_visit_stats_t3_date($timestamp)
{
    if ((int) $timestamp <= 0) return '-';
    $date = new DateTime('@' . (int) $timestamp);
    $date->setTimezone(new DateTimeZone(xz_visit_stats_rollup_timezone()));
    return xz_visit_stats_admin_escape($date->format('Y-m-d H:i:s'));
}

function xz_visit_stats_t3_filters($source = null)
{
    $filters = xz_visit_stats_v3_filters($source);
    if ($filters['range'] === 'all') $filters['range'] = '30d';
    return $filters;
}

function xz_visit_stats_t3_status($code)
{
    return '<span class="xz-status ' . xz_visit_stats_admin_status_class($code) . '">' . (int) $code . '</span>';
}

