<?php if ($view === 'performance') { $d=$data['duration']; ?><section class="xz-overview-section xzvs-v3-extension"><h2>服务器响应耗时分布</h2><p>已统计 <?php echo (int)$d['samples']; ?> 次访问。中位响应耗时：<?php echo $d['p50']===null?'暂无数据':number_format($d['p50'],1).' ms'; ?>；较慢的 25% 访问在 <?php echo $d['p75']===null?'暂无数据':number_format($d['p75'],1).' ms'; ?> 以内；最慢的 5% 访问在 <?php echo $d['p95']===null?'暂无数据':number_format($d['p95'],1).' ms'; ?> 以内。超过 1000ms 的访问有 <?php echo (int)$d['slow']; ?> 次。</p><p><a class="button" href="<?php echo xz_visit_stats_admin_escape(xz_visit_stats_t3_url('records',$filters,array('slow_ms'=>'1000'))); ?>">查看响应较慢的访问</a></p><h3>服务端响应变化</h3><table class="tableFull tableBorder"><thead><tr><th>日期</th><th>平均响应耗时</th><th>慢请求数</th></tr></thead><tbody><?php foreach($data['duration_trend'] as $r){ ?><tr><td><?php echo xz_visit_stats_admin_escape($r['day']); ?></td><td><?php echo number_format((float)$r['average'],1); ?> ms</td><td><?php echo (int)$r['slow']; ?></td></tr><?php } if(empty($data['duration_trend'])) { ?><tr><td colspan="3">当前时间范围暂无服务器耗时数据</td></tr><?php } ?></tbody></table></section><?php } ?>
